```javascript
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet()); // Sets security HTTP headers
app.use(express.json({ limit: '10kb' })); // Limit body size to prevent DoS

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Stricter rate limiting for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  message: 'Too many attempts, please try again later.',
});

// Input validation middleware
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    // Log validation failures for security monitoring
    console.warn(`[Security] Input validation failed: ${JSON.stringify(errors.array())}`);
    return res.status(400).json({
      error: 'Invalid input',
      details: errors.array().map(e => ({ field: e.path, message: e.msg }))
    });
  }
  next();
};

// Sanitization helper to prevent XSS
const sanitizeOutput = (data) => {
  if (typeof data === 'string') {
    return data.replace(/[<>]/g, '');
  }
  if (Array.isArray(data)) {
    return data.map(sanitizeOutput);
  }
  if (data && typeof data === 'object') {
    const sanitized = {};
    for (const [key, value] of Object.entries(data)) {
      sanitized[key] = sanitizeOutput(value);
    }
    return sanitized;
  }
  return data;
};

app.get('/health', (req, res) => {
  try {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  } catch (error) {
    console.error('[Error] Health check failed:', error.message);
    res.status(500).json({ error: 'Service unavailable' });
  }
});

app.get('/users', 
  [
    // Validate and sanitize query parameters
    query('id')
      .optional()
      .isInt({ min: 1 })
      .withMessage('ID must be a positive integer')
      .toInt(),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100')
      .toInt(),
    query('email')
      .optional()
      .isEmail()
      .withMessage('Email must be valid')
      .normalizeEmail(),
    query('sort')
      .optional()
      .isIn(['id', 'name', 'email'])
      .withMessage('Sort must be one of: id, name, email'),
  ],
  validateRequest,
  (req, res) => {
    try {
      const { id, limit, email, sort } = req.query;

      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      let filteredUsers = users;

      // Filter by ID if provided
      if (id) {
        filteredUsers = filteredUsers.filter(u => u.id === id);
      }

      // Filter by email if provided
      if (email) {
        filteredUsers = filteredUsers.filter(u => 
          u.email.toLowerCase() === email.toLowerCase()
        );
      }

      // Sort if requested (only allow safe fields)
      if (sort) {
        filteredUsers = [...filteredUsers].sort((a, b) => 
          a[sort] > b[sort] ? 1 : -1
        );
      }

      // Limit results
      if (limit && limit < filteredUsers.length) {
        filteredUsers = filteredUsers.slice(0, limit);
      }

      // Sanitize output to prevent XSS
      res.json(sanitizeOutput(filteredUsers));

    } catch (error) {
      console.error('[Error] Failed to fetch users:', error.message);
      res.status(500).json({ error: 'Failed to retrieve users' });
    }
  }
);

// Example of a sensitive endpoint with stricter rate limiting
app.post('/users',
  [
    body('name')
      .trim()
      .isLength({ min: 1, max: 100 })
      .withMessage('Name must be 1-100 characters')
      .escape(), // Prevent XSS
    body('email')
      .trim()
      .isEmail()
      .withMessage('Invalid email format')
      .normalizeEmail()
      .isLength({ max: 255 })
      .withMessage('Email too long'),
  ],
  validateRequest,
  strictLimiter,
  (req, res) => {
    try {
      // Process user creation...
      res.status(201).json({ message: 'User created successfully' });
    } catch (error) {
      console.error('[Error] User creation failed:', error.message);
      res.status(500).json({ error: 'Failed to create user' });
    }
  }
);

// 404 handler - must be after all routes
app.use((req, res) => {
  res.status(404).json({ error: 'Endpoint not found' });
});

// Global error handling middleware - must be last
app.use((err, req, res, next) => {
  // Log the full error for debugging (in production, use proper logging service)
  console.error('[Error] Unhandled error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    url: req.url,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Don't expose internal errors to client
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'development' 
    ? err.message 
    : 'An unexpected error occurred';

  res.status(statusCode).json({
    error: message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown handling
const shutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);
  server.close(() => {
    console.log('Server closed successfully');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('[Fatal] Uncaught exception:', err);
  shutdown('uncaughtException');
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('[Fatal] Unhandled rejection at:', promise, 'reason:', reason);
  shutdown('unhandledRejection');
});

module.exports = app;
```

---

### **Required package.json Additions:**

```json
{
  "dependencies": {
    "express": "^4.18.2",
    "helmet": "^7.1.0",
    "express-rate-limit": "^7.1.5",
    "express-validator": "^7.0.1"
  }
}
```

---

### **Key Security Improvements Summary:**

| Area | Improvement | Security Benefit |
|------|-------------|------------------|
| **Headers** | Added Helmet middleware | Protects against well-known vulnerabilities via HTTP headers |
| **Rate Limiting** | Configured per-endpoint limits | Prevents DoS and brute force attacks |
| **Input Validation** | Added express-validator | Prevents injection attacks and invalid data |
| **Output Sanitization** | XSS sanitization helper | Prevents cross-site scripting via API responses |
| **Body Limits** | 10KB JSON limit | Prevents memory exhaustion attacks |
| **Error Handling** | Global error middleware | Prevents information leakage via stack traces |
| **Logging** | Security-focused logging | Enables attack detection and forensics |
| **Graceful Shutdown** | Proper signal handling | Prevents data corruption and connection drops |
| **Uncaught Errors** | Process-level handlers | Prevents server crashes from unexpected errors |

---

### **Additional Recommendations:**

1. **Environment Variables**: Use a library like `dotenv` and validate required environment variables at startup
2. **HTTPS**: Use TLS in production (e.g., with `letsencrypt` or via reverse proxy)
3. **API Authentication**: Add JWT or API key authentication for protected endpoints
4. **Request ID**: Add request IDs for tracing and audit logs
5. **CSRF Protection**: Add CSRF tokens for state-changing operations
6. **CORS Configuration**: Restrict CORS to specific origins if needed
7. **Dependency Scanning**: Use `npm audit` and tools like Snyk or Dependabot
8. **Logging Service**: Integrate with a proper logging service (Winston, Pino, etc.)

