// Secure Express application with comprehensive error handling and input validation
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet()); // Security headers

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Body parsing with size limits to prevent overflow attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Request logging middleware (for security auditing)
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.path} - IP: ${req.ip}`);
  next();
});

// Middleware to handle validation errors
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg,
      })),
    });
  }
  next();
};

// Utility function to sanitize user input
const sanitizeInput = (input) => {
  if (typeof input !== 'string') return input;
  // Remove potentially dangerous characters
  return input
    .replace(/[<>]/g, '') // Remove angle brackets (XSS prevention)
    .trim()
    .substring(0, 1000); // Limit length
};

// Mock user database (in production, use a real database with parameterized queries)
const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Get users endpoint with input validation
app.get('/users', [
  // Validate query parameters
  query('id')
    .optional()
    .isInt({ min: 1, max: 1000 })
    .withMessage('ID must be a positive integer')
    .toInt(),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100')
    .toInt(),
  query('sort')
    .optional()
    .isIn(['name', 'email', 'id'])
    .withMessage('Sort must be one of: name, email, id'),
], handleValidationErrors, (req, res) => {
  try {
    let filteredUsers = [...users];

    // Filter by ID if provided
    if (req.query.id) {
      const sanitizedId = parseInt(req.query.id);
      if (isNaN(sanitizedId) || sanitizedId < 1) {
        return res.status(400).json({ error: 'Invalid ID' });
      }
      filteredUsers = filteredUsers.filter(user => user.id === sanitizedId);
    }

    // Apply limit if provided
    if (req.query.limit) {
      filteredUsers = filteredUsers.slice(0, req.query.limit);
    }

    // Apply sorting if provided (safe sorting - prevents SQL/NoSQL injection)
    if (req.query.sort) {
      const validSortFields = ['name', 'email', 'id'];
      if (validSortFields.includes(req.query.sort)) {
        filteredUsers.sort((a, b) => {
          if (a[req.query.sort] < b[req.query.sort]) return -1;
          if (a[req.query.sort] > b[req.query.sort]) return 1;
          return 0;
        });
      }
    }

    // Sanitize output data
    const sanitizedUsers = filteredUsers.map(user => ({
      id: user.id,
      name: sanitizeInput(user.name),
      email: sanitizeInput(user.email),
    }));

    res.json(sanitizedUsers);
  } catch (error) {
    console.error('Error retrieving users:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Example POST endpoint demonstrating body validation
app.post('/users', [
  body('name')
    .notEmpty()
    .withMessage('Name is required')
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters')
    .matches(/^[a-zA-Z\s'-]+$/)
    .withMessage('Name contains invalid characters'),
  body('email')
    .notEmpty()
    .withMessage('Email is required')
    .isEmail()
    .withMessage('Invalid email format')
    .normalizeEmail(),
], handleValidationErrors, (req, res) => {
  try {
    const { name, email } = req.body;

    // Check for duplicate email
    const emailExists = users.some(user => user.email === email);
    if (emailExists) {
      return res.status(409).json({ error: 'Email already exists' });
    }

    // Create new user (in production, insert into database with parameterized query)
    const newUser = {
      id: users.length + 1,
      name: sanitizeInput(name),
      email: sanitizeInput(email),
    };
    users.push(newUser);

    // Return safe response (don't expose internal IDs or sensitive data)
    res.status(201).json({
      message: 'User created successfully',
      user: {
        name: newUser.name,
        email: newUser.email,
      },
    });
  } catch (error) {
    console.error('Error creating user:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// 404 handler - must be after all routes
app.use((req, res) => {
  res.status(404).json({ error: 'Endpoint not found' });
});

// Global error handler - must be last
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't expose error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: 'Internal server error',
    ...(isDevelopment && { details: err.message }),
  });
});

// Graceful shutdown handling
const server = app.listen(3000, () => {
  console.log('Server running on port 3000');
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // In production, you might want to restart the process here
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, you might want to restart the process here
});

// Graceful shutdown on SIGTERM
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

