/**
 * Express Application with Enhanced Error Handling and Security
 * Follows OWASP security best practices
 */

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// Use Helmet for security headers (CSP, XSS Protection, HSTS, etc.)
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
  noSniff: true,
  xssFilter: true,
}));

// Configure body parser with security limits
app.use(express.json({
  limit: '10kb', // Limit body size to prevent DoS
  strict: true,  // Only accept objects and arrays
}));

app.use(express.urlencoded({
  extended: false,
  limit: '10kb',
}));

// Rate limiting to prevent DoS and brute force attacks
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.',
  },
  standardHeaders: true,
  legacyHeaders: false,
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Stricter limit for sensitive endpoints
  message: {
    error: 'Too many requests, please slow down.',
  },
});

// Apply rate limiting to all API routes
app.use('/api/', apiLimiter);

// ============================================================================
// REQUEST ID AND LOGGING (Placeholder for production logging system)
// ============================================================================

app.use((req, res, next) => {
  req.id = Math.random().toString(36).substring(2, 15);
  res.setHeader('X-Request-ID', req.id);
  console.log(`[${req.id}] ${req.method} ${req.path} - IP: ${req.ip}`);
  next();
});

// ============================================================================
// VALIDATION MIDDLEWARE
// ============================================================================

/**
 * Middleware to check validation results and return errors if any
 */
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path || err.param,
        message: err.msg,
        value: err.value,
      })),
      requestId: req.id,
    });
  }
  next();
};

/**
 * Sanitization helper for data output
 */
const sanitizeOutput = (data) => {
  // Remove any potentially dangerous content
  if (typeof data === 'string') {
    return data
      .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
      .trim()
      .substring(0, 1000); // Limit string length
  }
  return data;
};

/**
 * Safe response wrapper that applies sanitization
 */
const safeJson = (res, data, statusCode = 200) => {
  try {
    const sanitized = JSON.parse(JSON.stringify(data, (key, value) => sanitizeOutput(value)));
    return res.status(statusCode).json({
      success: true,
      data: sanitized,
      requestId: res.getHeader('X-Request-ID'),
    });
  } catch (error) {
    return res.status(500).json({
      success: false,
      error: 'Internal server error',
      requestId: res.getHeader('X-Request-ID'),
    });
  }
};

// ============================================================================
// INPUT VALIDATION SCHEMAS
// ============================================================================

const healthValidation = [
  query('format')
    .optional()
    .isIn(['json', 'text'])
    .withMessage('Format must be either "json" or "text"'),
];

const usersValidation = [
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer'),
  query('fields')
    .optional()
    .custom((value) => {
      const allowedFields = ['id', 'name', 'email'];
      const requestedFields = value.split(',');
      const invalidFields = requestedFields.filter(f => !allowedFields.includes(f));
      if (invalidFields.length > 0) {
        throw new Error(`Invalid fields: ${invalidFields.join(', ')}`);
      }
      return true;
    }),
];

// ============================================================================
// ROUTES WITH VALIDATION
// ============================================================================

app.get('/health', healthValidation, validateRequest, (req, res) => {
  try {
    const responseData = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    };

    if (req.query.format === 'text') {
      res.set('Content-Type', 'text/plain');
      return res.send(`OK - ${responseData.timestamp}`);
    }

    return safeJson(res, responseData);
  } catch (error) {
    console.error(`[${req.id}] Health check error:`, error);
    return safeJson(res, { status: 'error' }, 500);
  }
});

app.get('/users', usersValidation, validateRequest, (req, res) => {
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const limit = parseInt(req.query.limit) || users.length;
    const offset = parseInt(req.query.offset) || 0;

    // Field filtering
    let filteredUsers = users.slice(offset, offset + limit);
    if (req.query.fields) {
      const fields = req.query.fields.split(',');
      filteredUsers = filteredUsers.map(user => {
        const filtered = {};
        fields.forEach(field => {
          if (user[field] !== undefined) {
            filtered[field] = user[field];
          }
        });
        return filtered;
      });
    }

    return safeJson(res, {
      users: filteredUsers,
      meta: {
        total: users.length,
        returned: filteredUsers.length,
        limit,
        offset,
      },
    });
  } catch (error) {
    console.error(`[${req.id}] Users endpoint error:`, error);
    return safeJson(res, { error: 'Failed to retrieve users' }, 500);
  }
});

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

/**
 * 404 Not Found Handler
 */
app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: 'Not Found',
    message: `The requested endpoint ${req.method} ${req.path} does not exist.`,
    requestId: req.id,
  });
});

/**
 * Global Error Handler
 * Must be defined last, after all routes and middleware
 */
app.use((err, req, res, next) => {
  // Log the full error for debugging
  console.error(`[${req.id}] Error:`, {
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip,
  });

  // Determine status code
  const statusCode = err.statusCode || 500;
  const isDevelopment = process.env.NODE_ENV !== 'production';

  // Generic error message for production, detailed for development
  const errorMessage = isDevelopment ? err.message : 'An unexpected error occurred';

  // Handle specific error types
  if (err.type === 'entity.parse.failed') {
    return res.status(400).json({
      success: false,
      error: 'Invalid JSON',
      message: 'The request body contains invalid JSON.',
      requestId: req.id,
    });
  }

  if (err.type === 'entity.too.large') {
    return res.status(413).json({
      success: false,
      error: 'Payload Too Large',
      message: 'The request body exceeds the maximum allowed size.',
      requestId: req.id,
    });
  }

  // Handle validation errors
  if (err.name === 'ValidationError') {
    return res.status(400).json({
      success: false,
      error: 'Validation Error',
      details: err.errors,
      requestId: req.id,
    });
  }

  // Handle JSON syntax errors
  if (err instanceof SyntaxError && err.status === 400 && 'body' in err) {
    return res.status(400).json({
      success: false,
      error: 'Invalid JSON Syntax',
      requestId: req.id,
    });
  }

  // Default error response
  res.status(statusCode).json({
    success: false,
    error: errorMessage,
    ...(isDevelopment && { stack: err.stack }),
    requestId: req.id,
  });
});

/**
 * Handle unhandled promise rejections
 */
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, you might want to use a monitoring service here
});

/**
 * Handle uncaught exceptions
 */
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // In production, log to monitoring service and gracefully shutdown
  process.exit(1);
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

/**
 * Graceful shutdown handler
 */
const gracefulShutdown = () => {
  console.log('Received shutdown signal, closing server gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  // Force close after 10 seconds
  setTimeout(() => {
    console.error('Forcing server shutdown...');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

module.exports = app;

