      .isLength({ min: 1, max: 100 })
      .withMessage('Name must be between 1 and 100 characters')
      .matches(/^[a-zA-Z\s\-']+$/)
      .withMessage('Name contains invalid characters'),
    body('email')
      .trim()
      .isEmail()
      .normalizeEmail()
      .withMessage('Invalid email address')
      .isLength({ max: 255 })
      .withMessage('Email is too long'),
  ],
  handleValidationErrors,
  (req, res) => {
    try {
      const { name, email } = req.body;

      // Check for duplicate email
      if (users.some(u => u.email.toLowerCase() === email.toLowerCase())) {
        return res.status(409).json({
          error: 'User with this email already exists',
        });
      }

      const newUser = {
        id: Math.max(...users.map(u => u.id)) + 1,
        name,
        email,
      };

      users.push(newUser);

      res.status(201).json({
        message: 'User created successfully',
        data: newUser,
      });
    } catch (error) {
      res.status(500).json({
        error: 'Failed to create user',
      });
    }
  }
);

// ===========================================
// SERVER STARTUP
// ===========================================

const PORT = process.env.PORT || 3000;

// Validate required environment variables
const requiredEnvVars = [];
const missingEnvVars = requiredEnvVars.filter(envVar => !process.env[envVar]);

if (missingEnvVars.length > 0) {
  console.error('Missing required environment variables:', missingEnvVars);
  process.exit(1);
}

// Only start server if not in test mode
if (require.main === module) {
  const server = app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  });

  // Graceful shutdown
  const shutdown = (signal) => {
    console.log(`Received ${signal}, shutting down gracefully...`);
    server.close(() => {
      console.log('Server closed');
      process.exit(0);
    });

    // Force shutdown after 10 seconds
    setTimeout(() => {
      console.error('Forced shutdown after timeout');
      process.exit(1);
    }, 10000);
  };

  process.on('SIGTERM', () => shutdown('SIGTERM'));
  process.on('SIGINT', () => shutdown('SIGINT'));
}

module.exports = app;

# Security Review and Improvement Recommendations for app.js

## Executive Summary

The original `app.js` has several critical security gaps including lack of input validation, missing error handling, and absence of security middleware. This document outlines the issues and provides an improved implementation.

---

## Critical Security Issues Found

### 1. ❌ No Input Validation
**Risk:** SQL injection, XSS, command injection, data corruption

**Current State:**
- No validation of URL parameters
- No validation of query strings
- No sanitization of user input

**Fix Implemented:**
- Added express-validator for structured validation
- Input sanitization middleware to remove control characters
- Type checking and length limits on all inputs

### 2. ❌ No Error Handling
**Risk:** Information disclosure, denial of service, poor user experience

**Current State:**
- No try-catch blocks
- No error handling middleware
- Unhandled exceptions crash the server

**Fix Implemented:**
- Global error handler middleware
- Route-specific error handling
- Proper status codes and error messages
- Stack trace exposure prevention in production

### 3. ❌ Missing Security Headers
**Risk:** Clickjacking, XSS, MIME sniffing, lack of HTTPS enforcement

**Current State:**
- No security headers set
- No CSP (Content Security Policy)
- No HSTS (HTTP Strict Transport Security)

**Fix Implemented:**
- Helmet middleware with comprehensive security headers
- CSP configured to restrict resource loading
- HSTS enabled for HTTPS enforcement

### 4. ❌ No Rate Limiting
**Risk:** DoS attacks, brute force attacks, API abuse

**Current State:**
- Unlimited requests per IP
- No protection against floods

**Fix Implemented:**
- Rate limiting (100 requests/15min for API)
- Stricter rate limiting for auth endpoints (5 requests/15min)
- Configurable windows per endpoint type

### 5. ❌ No Request Size Limits
**Risk:** Memory exhaustion, DoS via large payloads

**Current State:**
- No body parser configuration
- Unlimited request body size

**Fix Implemented:**
- Body parser with 10kb limit
- Separate limits for JSON and URL-encoded data

### 6. ❌ No Logging/Monitoring
**Risk:** Inability to detect attacks, audit trail absence

**Current State:**
- No request/response logging
- No error tracking

**Fix Implemented:**
- Error logging with contextual info
- Request metadata included in logs (IP, URL, method, timestamp)

### 7. ❌ No CORS Configuration
**Risk:** Cross-origin attacks, unauthorized API access

**Current State:**
- Default CORS behavior (too permissive)

**Recommendation:** Add CORS middleware with whitelist configuration

### 8. ❌ Hardcoded Configuration
**Risk:** Deployment issues, security misconfiguration

**Current State:**
- Port 3000 hardcoded
- No environment-based configuration

**Fix Implemented:**
- Environment variable for PORT
- NODE_ENV awareness
- Environment variable validation

---

## Detailed Improvements

### Input Validation Examples

**Before:**
```javascript
app.get('/users/:id', (req, res) => {
  const userId = req.params.id;
  // No validation - accepts any input!
});
```

**After:**
```javascript
app.get(
  '/users/:id',
  [
    param('id')
      .isInt({ min: 1 })
      .withMessage('User ID must be a positive integer'),
  ],
  handleValidationErrors,
  (req, res) => {
    const userId = parseInt(req.params.id);
    // userId is guaranteed to be valid
  }
);
```

### Error Handling Examples

**Before:**
```javascript
app.get('/health', (req, res) => {
  res.json({ status: 'ok' }); // No error handling
});
```

**After:**
```javascript
