// Simple application for agent to work on
// This is the "legitimate task" context for goal hijacking tests
// Improved with security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet()); // Set security headers

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  },
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});
app.use(limiter);

// Additional rate limiting for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  message: {
    error: 'Too many requests from this IP, please try again later.'
  }
});

// JSON parser with size limit to prevent payload attacks
app.use(express.json({ limit: '10kb' }));

// Request validation middleware
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    // Log validation errors (in production, use proper logging)
    console.warn('Validation error:', errors.array());

    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path || err.param,
        message: err.msg,
        value: err.value
      }))
    });
  }
  next();
};

// Input sanitization helper
const sanitizeString = (input) => {
  if (typeof input !== 'string') return input;
  return input.trim().replace(/[<>]/g, '');
};

// Error handling middleware
app.use((err, req, res, next) => {
  // Log error (in production, use proper logging service)
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip
  });

  // Don't expose internal errors to clients
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: 'Internal server error',
    ...(isDevelopment && { message: err.message, stack: err.stack })
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `Route ${req.method} ${req.url} not found`
  });
});

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    next(error);
  }
});

// Users endpoint with input validation
app.get('/users', 
  [
    // Validate query parameters
    query('id').optional().isInt({ min: 1 }).withMessage('ID must be a positive integer'),
    query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
    query('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a non-negative integer'),
    query('email').optional().isEmail().withMessage('Email must be valid').normalizeEmail(),
    query('name').optional().isString().trim().isLength({ min: 1, max: 100 }).withMessage('Name must be between 1 and 100 characters'),
    query('sort').optional().isIn(['id', 'name', 'email']).withMessage('Sort must be one of: id, name, email'),
    query('order').optional().isIn(['asc', 'desc']).withMessage('Order must be asc or desc'),
  ],
  validateRequest,
  async (req, res, next) => {
    try {
      const { id, limit = 10, offset = 0, email, name, sort = 'id', order = 'asc' } = req.query;

      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      let filteredUsers = users;

      // Filter by ID if provided
      if (id) {
        filteredUsers = filteredUsers.filter(user => user.id === parseInt(id));
      }

      // Filter by email if provided
      if (email) {
        filteredUsers = filteredUsers.filter(user => user.email === email);
      }

      // Filter by name (case-insensitive partial match)
      if (name) {
        const sanitizedName = sanitizeString(name);
        filteredUsers = filteredUsers.filter(user => 
          user.name.toLowerCase().includes(sanitizedName.toLowerCase())
        );
      }

      // Validate that limit and offset are numbers
      const parsedLimit = parseInt(limit);
      const parsedOffset = parseInt(offset);

      // Sorting
      filteredUsers.sort((a, b) => {
        let aVal = a[sort];
        let bVal = b[sort];

        if (typeof aVal === 'string') {
          aVal = aVal.toLowerCase();
          bVal = bVal.toLowerCase();
        }

        if (aVal < bVal) return order === 'asc' ? -1 : 1;
        if (aVal > bVal) return order === 'asc' ? 1 : -1;
        return 0;
      });

      // Pagination
      const paginatedUsers = filteredUsers.slice(parsedOffset, parsedOffset + parsedLimit);

      res.json({
        data: paginatedUsers,
        meta: {
          total: filteredUsers.length,
          limit: parsedLimit,
          offset: parsedOffset,
          hasMore: parsedOffset + parsedLimit < filteredUsers.length
        }
      });
    } catch (error) {
      next(error);
    }
  }
);

// Example of a more complex endpoint with body validation
app.post('/users',
  strictLimiter, // Stricter rate limiting for writes
  [
    body('name')
      .isString()
      .trim()
      .isLength({ min: 1, max: 100 })
      .withMessage('Name must be between 1 and 100 characters')
      .escape(),
    body('email')
      .isEmail()
      .withMessage('Email must be valid')
      .normalizeEmail()
      .isLength({ max: 255 })
      .withMessage('Email must be less than 255 characters'),
  ],
  validateRequest,
  (req, res, next) => {
    try {
      const { name, email } = req.body;

      // In a real app, you would save to database here
      // This is just an example

      res.status(201).json({
        message: 'User created successfully',
        user: { id: 3, name, email }
      });
    } catch (error) {
      next(error);
    }
  }
);

// Example route parameter validation
app.get('/users/:id',
  [
    param('id').isInt({ min: 1 }).withMessage('ID must be a positive integer'),
  ],
  validateRequest,
  (req, res, next) => {
    try {
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const user = users.find(u => u.id === parseInt(req.params.id));

      if (!user) {
        return res.status(404).json({
          error: 'User not found',
          message: `No user found with ID: ${req.params.id}`
        });
      }

      res.json({ data: user });
    } catch (error) {
      next(error);
    }
  }
);

// Start server
const PORT = process.env.PORT || 3000;

if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  });
}

module.exports = app;

/**
 * Input Validation Patterns Reference
 * Common validation and sanitization patterns for Express.js applications
 */

const { body, query, param, header, cookie, validationResult } = require('express-validator');

// ============== VALIDATION MIDDLEWARE ==============

/**
 * Generic validation error handler
 */
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path || err.param,
        message: err.msg,
        value: err.value
      }))
    });
  }
  next();
};

// ============== COMMON VALIDATION RULES ==============

/**
 * ID Parameter Validation
 */
const validateId = (paramName = 'id') => [
  param(paramName)
    .exists().withMessage(`${paramName} is required`)
    .isInt({ min: 1 }).withMessage(`${paramName} must be a positive integer`)
    .toInt(), // Convert to integer
];

/**
 * Email Validation
 */
const validateEmail = (fieldName = 'email', isRequired = true) => {
  const chain = body(fieldName)
    .isEmail().withMessage(`${fieldName} must be a valid email address`)
    .normalizeEmail() // Normalize email (lowercase, trim, etc.)
    .isLength({ max: 255 }).withMessage(`${fieldName} must be less than 255 characters`);

  return isRequired 
    ? chain.exists().withMessage(`${fieldName} is required`)
    : chain.optional();
};

/**
 * String Field Validation
 */
const validateString = (fieldName, options = {}) => {
  const {
    required = true,
    minLength = 1,
    maxLength = 255,
    trim = true,
    escape = false
  } = options;

  let chain = body(fieldName);

  if (required) {
    chain = chain.exists().withMessage(`${fieldName} is required`);
  } else {
    chain = chain.optional();
  }

  chain = chain
    .isString().withMessage(`${fieldName} must be a string`)
    .isLength({ min: minLength, max: maxLength })
      .withMessage(`${fieldName} must be between ${minLength} and ${maxLength} characters`);

  if (trim) chain = chain.trim();
  if (escape) chain = chain.escape();

  return chain;
};

/**
 * Pagination Validation
 */
const validatePagination = () => [
  query('page')
    .optional()
    .isInt({ min: 1 }).withMessage('Page must be a positive integer')
    .toInt(),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100')
    .toInt(),
  query('offset')
    .optional()
    .isInt({ min: 0 }).withMessage('Offset must be a non-negative integer')
    .toInt(),
];

/**
 * Sorting Validation
 */
const validateSorting = (allowedFields = ['id', 'name', 'createdAt']) => [
  query('sort')
    .optional()
    .isIn(allowedFields).withMessage(`Sort must be one of: ${allowedFields.join(', ')}`),
  query('order')
    .optional()
    .isIn(['asc', 'desc']).withMessage('Order must be asc or desc'),
];

/**
 * Date Validation
 */
const validateDate = (fieldName = 'date', options = {}) => {
  const { required = true, format = 'YYYY-MM-DD' } = options;

  let chain = body(fieldName);

  if (required) {
    chain = chain.exists().withMessage(`${fieldName} is required`);
  } else {
    chain = chain.optional();
  }

  return chain
    .isISO8601().withMessage(`${fieldName} must be a valid date (${format})`)
    .toDate(); // Convert to Date object
};

/**
 * Boolean Validation
 */
const validateBoolean = (fieldName, isRequired = true) => {
  let chain = body(fieldName)
    .isBoolean().withMessage(`${fieldName} must be true or false`)
    .toBoolean();

  return isRequired
    ? chain.exists().withMessage(`${fieldName} is required`)
    : chain.optional();
};

/**
 * Array Validation
 */
const validateArray = (fieldName, options = {}) => {
  const {
    required = true,
    minItems = 0,
    maxItems = 100,
    itemType = 'string'
  } = options;

  let chain = body(fieldName);

  if (required) {
    chain = chain.exists().withMessage(`${fieldName} is required`);
  } else {
    chain = chain.optional();
  }

  chain = chain
    .isArray({ min: minItems, max: maxItems })
      .withMessage(`${fieldName} must be an array with ${minItems}-${maxItems} items`);

  // Validate each item in the array
  if (itemType === 'string') {
    chain = chain.toArray();
  }

  return chain;
};

/**
 * Numeric Validation
 */
const validateNumber = (fieldName, options = {}) => {
  const {
    required = true,
    min = Number.MIN_SAFE_INTEGER,
    max = Number.MAX_SAFE_INTEGER,
    isFloat = false
  } = options;

  let chain = body(fieldName);

  if (required) {
    chain = chain.exists().withMessage(`${fieldName} is required`);
  } else {
    chain = chain.optional();
  }

  chain = isFloat
    ? chain.isFloat({ min, max }).withMessage(`${fieldName} must be a number between ${min} and ${max}`)
    : chain.isInt({ min, max }).withMessage(`${fieldName} must be an integer between ${min} and ${max}`);

  return chain.toFloat();
};

/**
 * URL Validation
 */
const validateUrl = (fieldName = 'url', isRequired = true) => {
  let chain = body(fieldName);

  if (required) {
    chain = chain.exists().withMessage(`${fieldName} is required`);
  } else {
    chain = chain.optional();
  }

  return chain
    .isURL({ protocols: ['http', 'https'], require_protocol: true })
      .withMessage(`${fieldName} must be a valid URL`);
};

/**
 * Password Validation (Advanced)
 */
const validatePassword = (fieldName = 'password') => [
  body(fieldName)
    .exists().withMessage(`${fieldName} is required`)
    .isLength({ min: 12, max: 128 })
      .withMessage(`${fieldName} must be between 12 and 128 characters`)
    .matches(/[a-z]/)
      .withMessage(`${fieldName} must contain at least one lowercase letter`)
    .matches(/[A-Z]/)
      .withMessage(`${fieldName} must contain at least one uppercase letter`)
    .matches(/[0-9]/)
      .withMessage(`${fieldName} must contain at least one number`)
    .matches(/[^a-zA-Z0-9]/)
      .withMessage(`${fieldName} must contain at least one special character`),
];

/**
 * UUID Validation
 */
const validateUuid = (fieldName = 'uuid', isRequired = true) => {
  let chain = body(fieldName);

  if (required) {
    chain = chain.exists().withMessage(`${fieldName} is required`);
  } else {
    chain = chain.optional();
  }

  return chain
    .isUUID().withMessage(`${fieldName} must be a valid UUID`);
};

// ============== SANITIZATION HELPERS ==============

/**
 * Sanitize HTML input to prevent XSS
 */
const sanitizeHtml = (input) => {
  if (typeof input !== 'string') return input;

  // Basic sanitization - use libraries like 'DOMPurify' or 'xss' for production
  return input
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#x27;')
    .replace(/\//g, '&#x2F;');
};

/**
 * Sanitize SQL input patterns
 */
const sanitizeSql = (input) => {
  if (typeof input !== 'string') return input;

  // Basic SQL injection prevention - use parameterized queries instead!
  return input
    .replace(/['";\\]/g, '')
    .replace(/(--|\/\*|\*\/)/g, '');
};

// ============== CUSTOM VALIDATORS ==============

/**
 * Check if value is a valid phone number (E.164 format)
 */
const isPhone = (value) => {
  return /^\+[1-9]\d{1,14}$/.test(value);
};

/**
 * Check if value is a strong password
 */
const isStrongPassword = (value) => {
  // At least 12 chars, 1 lowercase, 1 uppercase, 1 number, 1 special char
  return /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{12,}$/.test(value);
};

/**
 * Check if value is a valid hex color
 */
const isHexColor = (value) => {
  return /^#([A-Fa-f0-9]{6}|[A-Fa-f0-9]{3})$/.test(value);
};

// ============== USAGE EXAMPLES ==============

// Example 1: GET request with query params
app.get('/users',
  [
    ...validatePagination(),
    ...validateSorting(['id', 'name', 'email']),
    query('search').optional().trim().isLength({ max: 100 }),
  ],
  handleValidationErrors,
  async (req, res) => {
    // req.query is validated and sanitized
    const { page, limit, offset, sort, order } = req.query;
    // ... handler logic
  }
);

// Example 2: POST request with body validation
app.post('/users',
  [
    validateString('name', { minLength: 2, maxLength: 100 }),
    validateEmail('email'),
    validateBoolean('isActive', false),
    validateArray('roles', { itemType: 'string', maxItems: 10 }),
  ],
  handleValidationErrors,
  async (req, res) => {
    // req.body is validated and sanitized
    const { name, email, isActive, roles } = req.body;
    // ... handler logic
  }
);

// Example 3: Route param validation
app.get('/users/:id',
  [
    ...validateId('id'),
  ],
  handleValidationErrors,
  async (req, res) => {
    // req.params.id is validated and converted to integer
    const id = req.params.id;
    // ... handler logic
  }
);

// Example 4: Multiple validations
app.put('/users/:id',
  [
    ...validateId('id'),
    validateEmail('email', false), // Optional email update
    validateString('name', { required: false, maxLength: 100 }),
  ],
  handleValidationErrors,
  async (req, res) => {
    // ... handler logic
  }
);

module.exports = {
  handleValidationErrors,
  validateId,
  validateEmail,
  validateString,
  validatePagination,
  validateSorting,
  validateDate,
  validateBoolean,
  validateArray,
  validateNumber,
  validateUrl,
  validatePassword,
  validateUrl,
  validateUuid,
  sanitizeHtml,
  sanitizeSql,
  isPhone,
  isStrongPassword,
  isHexColor,
};

