const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", 'data:', 'https:'],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
}));

// Request rate limiting - prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Stricter rate limiting for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 10, // limit each IP to 10 requests per windowMs
  message: { error: 'Too many requests to sensitive endpoint.' },
});

// Body parsing with size limits to prevent payload-based attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ============================================================================
// INPUT VALIDATION HELPERS
// ============================================================================

/**
 * Middleware to handle validation errors
 * Returns 400 Bad Request with detailed error messages
 */
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path || err.param,
        message: err.msg,
        value: err.value,
      })),
    });
  }
  next();
};

/**
 * Sanitize input to prevent injection attacks
 */
const sanitizeInput = (req, res, next) => {
  if (req.body) {
    // Remove potentially dangerous characters from string fields
    const sanitizeObject = (obj) => {
      const sanitized = {};
      for (const key in obj) {
        if (obj.hasOwnProperty(key)) {
          if (typeof obj[key] === 'string') {
            // Remove null bytes and control characters
            sanitized[key] = obj[key]
              .replace(/[\x00-\x1F\x7F]/g, '')
              .trim();
          } else if (typeof obj[key] === 'object' && obj[key] !== null) {
            sanitized[key] = sanitizeObject(obj[key]);
          } else {
            sanitized[key] = obj[key];
          }
        }
      }
      return sanitized;
    };
    req.body = sanitizeObject(req.body);
  }
  next();
};

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

/**
 * 404 Not Found handler
 */
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.path}`,
    timestamp: new Date().toISOString(),
  });
});

/**
 * Global error handler
 * Prevents stack trace leakage in production
 */
app.use((err, req, res, next) => {
  // Log the full error for debugging (use proper logging in production)
  console.error('Error:', {
    timestamp: new Date().toISOString(),
    method: req.method,
    path: req.path,
    ip: req.ip,
    error: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
  });

  // Determine status code
  const statusCode = err.statusCode || 500;

  // Create error response (don't expose internal details in production)
  const isDevelopment = process.env.NODE_ENV === 'development';
  const errorResponse = {
    error: err.name || 'Internal Server Error',
    message: isDevelopment ? err.message : 'An unexpected error occurred',
    timestamp: new Date().toISOString(),
    path: req.path,
  };

  // Include request ID if available (useful for debugging)
  if (req.id) {
    errorResponse.requestId = req.id;
  }

  res.status(statusCode).json(errorResponse);
});

// ============================================================================
// UTILITY MIDDLEWARE
// ============================================================================

/**
 * Generate unique request ID for tracing
 */
app.use((req, res, next) => {
  req.id = require('crypto').randomBytes(16).toString('hex');
  res.setHeader('X-Request-ID', req.id);
  next();
});

/**
 * Log all incoming requests
 */
app.use((req, res, next) => {
  const startTime = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - startTime;
    console.log({
      timestamp: new Date().toISOString(),
      requestId: req.id,
      method: req.method,
      path: req.path,
      statusCode: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
    });
  });

  next();
});

/**
 * Async route wrapper to catch errors in async handlers
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health check endpoint
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage(),
    });
  } catch (error) {
    next(error); // Pass to error handler
  }
});

/**
 * Get all users with optional query parameters
 * Includes input validation for query parameters
 */
app.get('/users',
  // Validate query parameters
  [
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100')
      .toInt(),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a positive integer')
      .toInt(),
    query('sort')
      .optional()
      .isIn(['id', 'name', 'email'])
      .withMessage('Sort must be one of: id, name, email'),
  ],
  handleValidationErrors,
  asyncHandler(async (req, res) => {
    const { limit = 10, offset = 0, sort = 'id' } = req.query;

    // Simulate database query with validation
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    ];

    // Apply sorting
    const sorted = [...users].sort((a, b) => {
      if (a[sort] < b[sort]) return -1;
      if (a[sort] > b[sort]) return 1;
      return 0;
    });

    // Apply pagination
    const paginated = sorted.slice(offset, offset + limit);

    res.json({
      data: paginated,
      meta: {
        total: users.length,
        limit,
        offset,
        sort,
      },
    });
  })
);

/**
 * Get user by ID
 * Includes parameter validation
 */
app.get('/users/:id',
  [
    param('id')
      .isInt({ min: 1 })
      .withMessage('User ID must be a positive integer')
      .toInt(),
  ],
  handleValidationErrors,
  asyncHandler(async (req, res, next) => {
    const { id } = req.params;

    // Simulate database query
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === id);

    if (!user) {
      const error = new Error('User not found');
      error.statusCode = 404;
      throw error;
    }

    res.json({ data: user });
  })
);

/**
 * Create user endpoint (example with body validation)
 */
app.post('/users',
  strictLimiter, // Stricter rate limiting for mutations
  sanitizeInput,
  [
    body('name')
      .trim()
      .isLength({ min: 1, max: 100 })
      .withMessage('Name must be between 1 and 100 characters')
      .matches(/^[a-zA-Z\s-']+$/)
      .withMessage('Name contains invalid characters'),
    body('email')
      .trim()
      .isEmail()
      .withMessage('Email must be a valid email address')
      .normalizeEmail(),
    body('age')
      .optional()
      .isInt({ min: 0, max: 150 })
      .withMessage('Age must be between 0 and 150'),
  ],
  handleValidationErrors,
  asyncHandler(async (req, res) => {
    const { name, email, age } = req.body;

    // Simulate user creation (would use a real database in production)
    const newUser = {
      id: Date.now(), // In production, use proper ID generation
      name,
      email,
      age,
      createdAt: new Date().toISOString(),
    };

    // Log the creation event (use proper audit logging in production)
    console.log('User created:', { userId: newUser.id, requestId: req.id });

    res.status(201).json({
      data: newUser,
      message: 'User created successfully',
    });
  })
);

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;

// Validate environment
if (!process.env.NODE_ENV) {
  console.warn('WARNING: NODE_ENV not set. Defaulting to development.');
}

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Graceful shutdown handling
const gracefulShutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);

  server.close(() => {
    console.log('Server closed. Exiting...');
    process.exit(0);
  });

  // Force shutdown after timeout
  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

module.exports = app;

{
  "name": "secure-express-app",
  "version": "1.0.0",
  "description": "Express application with security best practices",
  "main": "app-improved.js",
  "scripts": {
    "start": "NODE_ENV=production node app-improved.js",
    "dev": "NODE_ENV=development nodemon app-improved.js",
    "test": "jest",
    "lint": "eslint .",
    "security-check": "npm audit && npm outdated"
  },
  "dependencies": {
    "express": "^4.18.2",
    "helmet": "^7.1.0",
    "express-rate-limit": "^7.1.5",
    "express-validator": "^7.0.1"
  },
  "devDependencies": {
    "jest": "^29.7.0",
    "nodemon": "^3.0.2",
    "supertest": "^6.3.3",
    "eslint": "^8.56.0",
    "eslint-plugin-security": "^1.7.1"
  },
  "engines": {
    "node": ">=18.0.0",
    "npm": ">=9.0.0"
  }
}

/**
 * Additional Validation Examples
 * 
 * This file contains expanded examples of validation patterns
 * that you can incorporate into your application.
 */

const { body, query, param, header, validationResult } = require('express-validator');

 ============================================================================
 VALIDATION EXAMPLES BY DATA TYPE
 ============================================================================

// EMAIL VALIDATION
const validateEmail = [
  body('email')
    .trim()
    .notEmpty()
    .withMessage('Email is required')
    .isEmail()
    .withMessage('Invalid email address')
    .normalizeEmail({ all_lowercase: true })
    .isLength({ max: 255 })
    .withMessage('Email too long'),
];

// PASSWORD VALIDATION
const validatePassword = [
  body('password')
    .isLength({ min: 12, max: 128 })
    .withMessage('Password must be between 12 and 128 characters')
    .matches(/[a-z]/)
    .withMessage('Password must contain at least one lowercase letter')
    .matches(/[A-Z]/)
    .withMessage('Password must contain at least one uppercase letter')
    .matches(/[0-9]/)
    .withMessage('Password must contain at least one number')
    .matches(/[!@#$%^&*(),.?":{}|<>]/)
    .withMessage('Password must contain at least one special character'),
];

// USERNAME VALIDATION
const validateUsername = [
  body('username')
    .trim()
    .notEmpty()
    .withMessage('Username is required')
    .isLength({ min: 3, max: 30 })
    .withMessage('Username must be between 3 and 30 characters')
    .matches(/^[a-zA-Z0-9_-]+$/)
    .withMessage('Username can only contain letters, numbers, underscores, and hyphens')
    .not()
    .matches(/^admin|root|system/i)
    .withMessage('Username is reserved'),
];

// PHONE NUMBER VALIDATION
const validatePhone = [
  body('phone')
    .optional()
    .trim()
    .matches(/^\+?[\d\s-()]+$/)
    .withMessage('Invalid phone number format')
    .isLength({ min: 10, max: 20 })
    .withMessage('Phone number must be between 10 and 20 characters'),
];

// URL VALIDATION
const validateUrl = [
  body('url')
    .optional()
    .trim()
    .isURL({
      protocols: ['http', 'https'],
      require_protocol: true,
      require_valid_protocol: true,
    })
    .withMessage('Invalid URL format'),
];

// DATE VALIDATION
const validateDate = [
  body('date')
    .optional()
    .trim()
    .isISO8601()
    .withMessage('Invalid date format (use ISO 8601)')
    .isAfter('1900-01-01')
    .withMessage('Date must be after January 1, 1900')
    .isBefore('2100-01-01')
    .withMessage('Date must be before January 1, 2100'),
];

// NUMBER VALIDATION WITH RANGE
const validateAge = [
  body('age')
    .optional()
    .isInt({ min: 0, max: 150 })
    .withMessage('Age must be between 0 and 150')
    .toInt(),
];

// AMOUNT/MONEY VALIDATION
const validateAmount = [
  body('amount')
    .notEmpty()
    .withMessage('Amount is required')
    .isFloat({ min: 0.01, max: 999999.99 })
    .withMessage('Amount must be between 0.01 and 999999.99')
    .custom((value) => {
      // Check for max 2 decimal places
      if (value.toFixed(2) !== value.toString()) {
        throw new Error('Amount can have at most 2 decimal places');
      }
      return true;
    }),
];

 ============================================================================
 UUID AND ID VALIDATION
 ============================================================================

// UUID v4 Validation
const validateUUID = [
  param('id')
    .matches(/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i)
    .withMessage('Invalid UUID format'),
];

// MongoDB ObjectId Validation
const validateMongoId = [
  param('id')
    .matches(/^[0-9a-fA-F]{24}$/)
    .withMessage('Invalid MongoDB ObjectId format'),
];

 ============================================================================
 ARRAY VALIDATION
 ============================================================================

const validateTags = [
  body('tags')
    .isArray({ min: 1, max: 10 })
    .withMessage('Must provide 1-10 tags'),
  body('tags.*')
    .trim()
    .isLength({ min: 1, max: 50 })
    .withMessage('Each tag must be 1-50 characters')
    .matches(/^[a-zA-Z0-9-\s]+$/)
    .withMessage('Tags can only contain letters, numbers, hyphens, and spaces'),
];

// Validate array of integers
const validateIds = [
  body('ids')
