const handleStrictValidation = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Invalid request data',
      details: errors.array(),
    });
  }

  // Check for unexpected fields
  const expectedFields = [...errors.mapped()].keys();
  const receivedFields = Object.keys(req.body);
  const unexpectedFields = receivedFields.filter(f => !expectedFields.includes(f));

  if (unexpectedFields.length > 0) {
    return res.status(400).json({
      error: 'Unexpected fields in request body',
      unexpected: unexpectedFields,
    });
  }

  next();
};

/**
 * Sanitize phone number to standard format
 */
const sanitizePhoneNumber = (value) => {
  if (!value) return value;
