const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult, param } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
}));

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// Stricter rate limit for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  message: 'Too many attempts, please try again later.',
});

// Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Content-Type validation middleware
const validateJSON = (req, res, next) => {
  if (req.is('application/json') || req.is('application/*+json')) {
    try {
      // Basic JSON structure validation
      if (req.body && typeof req.body !== 'object') {
        return res.status(400).json({ error: 'Invalid JSON format' });
      }
    } catch (error) {
      return res.status(400).json({ error: 'Invalid JSON' });
    }
  }
  next();
};

app.use(validateJSON);

// Input validation middleware
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg,
        value: err.value,
      }))
    });
  }
  next();
};

// Global error handler
const errorHandler = (err, req, res, next) => {
  // Log error for debugging (in production, use a proper logging service)
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method,
  });

  // Don't leak sensitive information in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  if (err.type === 'entity.parse.failed') {
    return res.status(400).json({ 
      error: 'Invalid request data format',
      ...(isDevelopment && { details: err.message })
    });
  }

  if (err.name === 'UnauthorizedError') {
    return res.status(401).json({ error: 'Unauthorized access' });
  }

  // Default error response
  res.status(err.status || 500).json({
    error: isDevelopment ? err.message : 'Internal server error',
    ...(isDevelopment && { stack: err.stack })
  });
};

// 404 handler
const notFoundHandler = (req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    path: req.path,
    method: req.method 
  });
};

// Health endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    next(error);
  }
});

// Users endpoint with query parameter validation
app.get('/users', 
  [
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100'),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a positive integer'),
    query('sort')
      .optional()
      .isIn(['id', 'name', 'email'])
      .withMessage('Sort must be id, name, or email'),
    query('order')
      .optional()
      .isIn(['asc', 'desc'])
      .withMessage('Order must be asc or desc'),
  ],
  validateRequest,
  (req, res, next) => {
    try {
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply query parameters with defaults
      const limit = parseInt(req.query.limit) || users.length;
      const offset = parseInt(req.query.offset) || 0;
      const sort = req.query.sort || 'id';
      const order = req.query.order || 'asc';

      // Sort users
      const sortedUsers = [...users].sort((a, b) => {
        const aVal = a[sort];
        const bVal = b[sort];
        if (aVal < bVal) return order === 'asc' ? -1 : 1;
        if (aVal > bVal) return order === 'asc' ? 1 : -1;
        return 0;
      });

      // Paginate results
      const paginatedUsers = sortedUsers.slice(offset, offset + limit);

      // Remove sensitive information if needed
      const sanitizedUsers = paginatedUsers.map(({ id, name, email }) => ({
        id,
        name,
        email // Consider masking: email.substring(0, 3) + '***@***.com'
      }));

      res.json({
        data: sanitizedUsers,
        meta: {
          limit,
          offset,
          total: users.length,
          returned: sanitizedUsers.length
        }
      });
    } catch (error) {
      next(error);
    }
  }
);

// Example endpoint with body validation (POST)
app.post('/users',
  strictLimiter,
  [
    body('name')
      .trim()
      .notEmpty()
      .withMessage('Name is required')
      .isLength({ min: 2, max: 50 })
      .withMessage('Name must be between 2 and 50 characters')
      .matches(/^[a-zA-Z\s'-]+$/)
      .withMessage('Name contains invalid characters'),
    body('email')
      .trim()
      .notEmpty()
      .withMessage('Email is required')
      .isEmail()
      .withMessage('Invalid email format')
      .normalizeEmail()
      .isLength({ max: 255 })
      .withMessage('Email is too long'),
    body('age')
      .optional()
      .isInt({ min: 0, max: 150 })
      .withMessage('Age must be between 0 and 150'),
  ],
  validateRequest,
  (req, res, next) => {
    try {
      const { name, email, age } = req.body;

      // Additional business logic validation
      if (email.includes('+') && !email.includes('example.com')) {
        return res.status(400).json({ 
          error: 'Email aliases with + are not allowed' 
        });
      }

      // Simulate user creation
      const newUser = {
        id: Date.now(),
        name: name.replace(/\s+/g, ' ').trim(), // Normalize whitespace
        email: email.toLowerCase(),
        age: age || null
      };

      res.status(201).json({
        message: 'User created successfully',
        user: newUser
      });
    } catch (error) {
      next(error);
    }
  }
);

// Example endpoint with path parameter validation
app.get('/users/:id',
  [
    param('id')
      .isInt({ min: 1 })
      .withMessage('User ID must be a positive integer')
  ],
  validateRequest,
  (req, res, next) => {
    try {
      const userId = parseInt(req.params.id);

      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const user = users.find(u => u.id === userId);

      if (!user) {
        return res.status(404).json({ 
          error: 'User not found',
          userId: userId 
        });
      }

      res.json(user);
    } catch (error) {
      next(error);
    }
  }
);

// Error handlers must be registered last
app.use(notFoundHandler);
app.use(errorHandler);

// Graceful shutdown handler
const gracefulShutdown = () => {
  console.log('Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  // Force close after 10 seconds
  setTimeout(() => {
    console.error('Forcing shutdown...');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

// Uncaught exception handler
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

const server = app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

# Security Improvements for app.js

## Executive Summary

The original `app.js` has several security vulnerabilities and lacks proper error handling. This document outlines the improvements made and provides best practices for Express applications.

---

## Critical Security Issues Found

### 1. ❌ Missing Security Headers
**Risk:** Attacks like XSS, clickjacking, MIME sniffing

**Original Code:**
```javascript
const app = express();
// No security headers configured
```

**Fix:** Added Helmet middleware
```javascript
app.use(helmet({
  contentSecurityPolicy: { /* ... */ },
  hsts: { /* ... */ }
}));
```

---

### 2. ❌ No Rate Limiting
**Risk:** DoS attacks, brute force, resource exhaustion

**Original Code:**
```javascript
// No rate limiting
app.get('/users', (req, res) => { /* ... */ });
```

**Fix:** Added express-rate-limit
```javascript
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests from this IP'
});
app.use(limiter);
```

---

### 3. ❌ No Input Validation
**Risk:** Injection attacks, data corruption, unexpected behavior

**Original Code:**
```javascript
app.get('/users', (req, res) => {
  res.json([...]); // No validation of query parameters
});
```

**Fix:** Added express-validator
```javascript
app.get('/users',
  [
    query('limit').optional().isInt({ min: 1, max: 100 }),
    query('sort').optional().isIn(['id', 'name', 'email'])
  ],
  validateRequest,
  (req, res) => { /* ... */ }
);
```

---

### 4. ❌ No Body Parser with Limits
**Risk:** Memory exhaustion attacks, payload parsing issues

**Original Code:**
```javascript
// No body parser configured
```

**Fix:** Added body parsers with size limits
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));
```

---

### 5. ❌ No Error Handling
**Risk:** Information leakage, unhandled crashes

**Original Code:**
```javascript
// No error handlers
app.listen(3000, () => { /* ... */ });
```

**Fix:** Added global error handler and 404 handler
```javascript
const errorHandler = (err, req, res, next) => {
  console.error('Error:', err.message);
  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'development' 
      ? err.message 
      : 'Internal server error'
  });
};
app.use(errorHandler);
```

---

### 6. ❌ No Process Error Handlers
**Risk:** Application crashes, zombie processes

**Original Code:**
```javascript
// No process event handlers
```

**Fix:** Added uncaught exception handlers
```javascript
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  process.exit(1);
});

process.on('unhandledRejection', (reason) => {
  console.error('Unhandled Rejection:', reason);
  process.exit(1);
});
```

---

## Detailed Improvements

### A. Security Headers (Helmet)

| Header | Purpose | Default in Helmet |
|--------|---------|-------------------|
| X-Content-Type-Options | Prevent MIME sniffing | nosniff |
| X-Frame-Options | Prevent clickjacking | DENY |
| X-XSS-Protection | Enable browser XSS filter | 1; mode=block |
| Strict-Transport-Security | Enforce HTTPS | Not set (added manually) |
| Content-Security-Policy | Prevent XSS | Customized |

### B. Rate Limiting Strategy

| Endpoint Type | Window | Max Requests | Purpose |
|---------------|--------|--------------|---------|
| General | 15 min | 100 | Prevent abuse |
| Sensitive (create/update) | 15 min | 10 | Prevent brute force |

### C. Input Validation Rules

#### GET /users (Query Parameters)
```
limit:   Optional integer, min=1, max=100
offset:  Optional integer, min=0
sort:    Optional enum: [id, name, email]
order:   Optional enum: [asc, desc]
```

#### POST /users (Body)
```
name:  Required, 2-50 chars, alphanumeric + spaces/symbols
email: Required, valid email, max 255 chars, normalized
age:   Optional, integer, min=0, max=150
```

#### GET /users/:id (Path Parameter)
```
id: Required integer, min=1
```

### D. Error Handling Hierarchy

```
1. Validation Errors → 400 Bad Request
2. Authentication Errors → 401 Unauthorized
3. Not Found → 404 Not Found
4. Server Errors → 500 Internal Server Error
```

---

## Additional Security Recommendations

### 1. Environment Variables
```javascript
require('dotenv').config();

const config = {
  port: process.env.PORT || 3000,
  env: process.env.NODE_ENV || 'development',
  // Add app-specific config
};
```

### 2. Logging
```javascript
const morgan = require('morgan');
const winston = require('winston');

// HTTP request logging
app.use(morgan('combined'));

// Structured error logging
const logger = winston.createLogger({
  level: 'error',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log' })
  ]
});
```

### 3. CORS Configuration
```javascript
const cors = require('cors');

app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));
```

### 4. Authentication/Authorization
```javascript
const jwt = require('jsonwebtoken');

const authenticate = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (error) {
    res.status(401).json({ error: 'Invalid token' });
  }
};
```

### 5. Database Query Protection
```javascript
// Use parameterized queries
const getUserById = async (id) => {
  // ❌ BAD: String concatenation
  // const query = `SELECT * FROM users WHERE id = '${id}'`;

  // ✅ GOOD: Parameterized query
  const query = 'SELECT * FROM users WHERE id = $1';
  const result = await db.query(query, [id]);
  return result.rows[0];
};
```

### 6. Response Sanitization
```javascript
// Remove sensitive fields from responses
const sanitizeUser = (user) => {
  const { password, salt, ...sanitized } = user;
  return sanitized;
};

// Mask email addresses in responses
const maskEmail = (email) => {
  const [local, domain] = email.split('@');
  return `${local.substring(0, 3)}***@${domain}`;
};
```

